        body: 'برای آرام کردن لثه‌های ملتهب کودک، روش‌های فیزیکی و خنک‌کننده در کنار اجرای [پروتکل گام‌به‌گام بهداشت دهان نوزاد](/articles/baby-bottle-tooth-decay-and-infant-oral-hygiene#infant-oral-hygiene-protocol-step-by-step) بهترین و کم‌خطرترین گزینه‌ها هستند:\n\n۱. **ماساژ ملایم لثه:** با دست‌های کاملاً شسته و تمیز، یا با یک گاز استریل مرطوب و خنک، یا مسواک انگشتی نرم، لثه ملتهب را با فشار ملایم ماساژ دهید.\n۲. **دندان‌گیر خنک سیلیکونی:** دندان‌گیر‌های بهداشتی و استاندارد (فاقد مواد مضر شیمیایی) را در یخچال (نه در فریزر!) بگذارید تا خنک شود؛ سرمای ملایم باعث جمع شدن رگ‌های خونی موضعی، کاهش موقت التهاب و تسکین فوری خارش می‌شود (اجسام یخ‌زده فریزری می‌توانند بافت لثه را بسوزانند).\n۳. **پارچه مرطوب و تمیز خنک:** یک دستمال نخی تمیز را با آب جوشیده سرد نم‌دار کرده، در یخچال خنک کنید و به کودک اجازه دهید آن را بجود.\n۴. **خشک کردن مداوم دور دهان و چانه:** برای جلوگیری از ایجاد جوش‌ها و دانه‌های پوستی ناشی از آبریزش مداوم بزاق، پوست چانه نوزاد را با پارچه نرم به آرامی خشک کنید.',
