        body: 'مکیدن یک واکنش طبیعی، آرام‌بخش و غریزی در نوزادان است که احساس امنیت به آن‌ها می‌بخشد. با این حال، اگر این عادت پس از رویش دندان‌های شیری و در سنین نوپایی همچنان با شدت ادامه یابد، نیروهای مکانیکی نامتناسبی به استخوان‌های در حال رشد فک وارد می‌سازد.\n\nشایع‌ترین آسیب‌های ناشی از مکیدن طولانی‌مدت انگشت و پستانک:\n- **اپن‌بایت (فاصله عمودی بین دندان‌های جلو):** ایجاد فاصله عمودی میان دندان‌های جلویی بالا و پایین به‌طوری که هنگام بستن دهان، دندان‌های جلو به هم نمی‌رسند.\n- **جلوزدگی دندان‌های بالا:** هل داده شدن دندان‌های پیشین فک بالا به سمت بیرون که احتمال ضربه و شکستگی آن‌ها را افزایش می‌دهد.\n- **تنگی فک بالا و کراس‌بایت خلفی (جفت نشدن دندان‌های آسیاب عقب):** ایجاد سقف دهان گنبدی و باریک به دلیل فشار مداوم عضلات گونه حین مکیدن.\n- **اختلالات گفتاری و تلفظی:** نوک‌زبانی صحبت کردن کودک و ناتوانی در تلفظ صحیح حروفی مانند «س» و «ز».',
