        body: 'با رعایت چند نکته ساده و بسیار کاربردی، می‌توانید میزان تماس قطره آهن با دندان‌های جلویی را به حداقل برسانید:\n\n۱. **استفاده از قطره‌چکان در انتهای دهان:** سر قطره‌چکان را در گوشه لپ و انتهای زبان (پشت دندان‌ها) قرار دهید تا دارو مستقیماً وارد گلو شده و با دندان‌های جلو تماس پیدا نکند.\n۲. **نوشاندن بلافاصله آب:** بلافاصله پس از دادن قطره، چند جرعه آب جوشیده خنک به کودک بنوشانید تا باقی‌مانده دارو از محیط دهان شسته شود.\n۳. **پاک کردن دندان‌ها با گاز یا مسواک:** سطح دندان‌های کودک را بلافاصله پس از مصرف قطره با یک گاز مرطوب، پد تمیز یا مسواک انگشتی تمیز نمایید.\n۴. **مخلوط کردن با آبمیوه طبیعی:** در کودکان بالای یک سال، می‌توانید قطره را با مقدار کمی آب پرتقال یا آب سیب طبیعی رقیق کرده و با نی به کودک بدهید (ویتامین C جذب آهن را نیز افزایش می‌دهد).',
