        body: 'دومین باور غلط این است که «قبل از جرم‌گیری دندان‌هایم محکم بودند، اما بعد از آن لق شدند و بین آن‌ها فاصله افتاد!» این تجربه برای برخی بیماران واقعی به نظر می‌رسد، اما علت آن کاملاً متفاوت از تصور عمومی است:\n\n۱. **جرم در نقش سیمان کاذب:**\nوقتی فردی سال‌ها جرم‌گیری نکرده و مبتلا به بیماری لثه (پریودنتیت) است، سموم باکتری‌ها استخوان نگه‌دارنده فک را آرام‌آرام آب می‌کنند. هم‌زمان، لایه‌های ضخیم جرم تمام فضای بین دندان‌ها را پر کرده و دندان‌های لق‌شده را مانند یک داربست یا آتل سنگی به هم می‌چسبانند. بیمار تا زمانی که این جرم‌ها وجود دارند احساس لقی نمی‌کند، چون این دیواره گچی دندان‌ها را مهار کرده است!\n\n۲. **برداشتن نقاب عفونت:**\nهنگامی که دندانپزشک این لایه‌های آلوده را برمی‌دارد، مهار کاذب حذف شده و لقی واقعی ناشی از تخریب قبلی استخوان آشکار می‌گردد. باقی ماندن این جرم‌ها نه تنها دندان را نجات نمی‌داد، بلکه با ادامه تحلیل استخوان ظرف یکی دو سال منجر به کشیدن قطعی تمام دندان‌ها می‌شد.\n\n۳. **باز شدن فواصل دندانی:**\nفضایی که پس از جرم‌گیری در پایین دندان‌ها احساس می‌شود، همان فاصله‌ای است که پیش‌تر توسط بافت ملتهب و متورم لثه یا رسوبات زرد و قهوه‌ای اشغال شده بود. با پاکسازی محیط، ورم لثه می‌خوابد و به سلامت طبیعی بازمی‌گردد که احساس خنکی و فضای خالی طبیعی به همراه دارد.',
