        body: 'مسواک زدن هر چقدر هم دقیق باشد، تنها سطوح بیرونی، درونی و جونده دندان را تمیز می‌کند و به دیواره‌های چسبیده بین دو دندان هیچ دسترسی ندارد. ۴۰ درصد پوسیدگی‌ها و بیش از ۸۰ درصد بیماری‌های لثه دقیقاً از همین فضاهای بین دندانی آغاز می‌شوند.\n\n- **اول نخ دندان یا اول مسواک؟**\nمطالعه بالینی منتشرشده در مجله تخصصی پریودنتولوژی (۲۰۱۸) نشان داده است که کشیدن نخ دندان **پیش از مسواک زدن** دو مزیت بزرگ دارد: نخست اینکه ذرات غذایی و پلاک را از بین دندان‌ها بیرون می‌کشد، و دوم اینکه اجازه می‌دهد کف حاوی فلوراید خمیردندان در مرحله بعد وارد درزهای خالی شده دندان‌ها شود و مقاومت بین‌دندانی را افزایش دهد.\n\n- **مسواک‌های مخصوص بین‌دندانی:**\nبرای افرادی که به دلیل تحلیل لثه بین دندان‌هایشان فاصله باز شده، یا ایمپلنت و پروتز دارند، نخ دندان معمولی ممکن است به تنهایی کافی نباشد. مسواک‌های کوچک استوانه‌ای یا مخروطی بین‌دندانی بهترین ابزار برای پاکسازی دیواره‌های عریض و حفظ پایه‌های ایمپلنت هستند.',
