        body: 'از گذشته این باور سنتی وجود داشته که نمک به دلیل خواص ضدعفونی‌کننده، بهترین ماده برای شستشوی دندان است. در این میان باید بین **غرغره محلول آب‌نمک رقیق ولرم** و **مسواک زدن مستقیم با نمک خشک** تفاوت قائل شد:\n\n- **آب‌نمک رقیق ولرم (مفید و ایمن):** یک شستشوی ملایم، التیام‌بخش و تسکین‌دهنده التهاب بعد از جراحی‌ها است.\n- **مسواک زدن با دانه‌های نمک (بسیار مخرب):** بلورهای نمک خوراکی یا نمک دریا ساختاری مکعبی با لبه‌های بسیار سخت و کریستالی دارند. مالیدن این بلورها با فرچه مسواک روی دندان، باعث ایجاد ریزخراش‌های عمیق روی مینا می‌شود. علاوه بر سایش مینا، مالش نمک غلیظ بافت ظریف لثه را دچار کم‌آبی شدید بافتی، سوزش و التهاب موضعی می‌کند.',
