        body: 'یکی از خطرناک‌ترین نسخه‌های خانگی اینترنتی، غرغره سرکه سیب، آبلیموی طبیعی یا ترکیب سرکه با جوش شیرین برای زدودن جرم دندان است.\n\n- **مرز اسیدی شدن یا نقطه بحرانی حل شدن مینا:**\nمینای دندان در pH کمتر از ۵.۵ شروع به از دست دادن مواد معدنی و حل شدن شیمیایی می‌کند. این در حالی است که سرکه و آبلیمو دارای اسیدیته بسیار بالا و **pH خطرناک ۲.۲ تا ۳.۰** هستند! تماس مکرر سرکه با دندان، کریستال‌های کلسیم و فسفات مینا را در عرض چند ثانیه به صورت شیمیایی در خود حل می‌کند.\n\n- **علائم فرسایش اسیدی دندان:**\n۱. لبه‌های شیشه‌ای و شفاف شدن دندان‌های جلو.\n۲. گود رفتگی و از بین رفتن برجستگی‌های طبیعی دندان.\n۳. دردهای وحشتناک و گزگز با کوچک‌ترین تماس باد یا آب سرد.\n۴. مینایی که با اسید حل شده است هرگز دوباره رشد نخواهد کرد و تنها با درمان‌های روکش و ونیرهای محافظتی پوشانده می‌شود.',
