    tldr: 'تحلیل لثه با کنار زدن بافت نرم و نمایان کردن ریشه بدون مینا، عامل اصلی تیر کشیدن دندان به آب سرد است؛ در مراحل اولیه با خمیردندان ضدحساسیت و ترمیم کامپوزیت طوق مهار می‌شود، اما در تحلیل‌های عمیق جراحی پیوند بافت همبند (پیوند لثه) ریشه را مجدداً پوشش می‌دهد.',
