        title: 'شیرین‌کننده‌های مصنوعی و قندهای الکلی؛ نجات مینای دندان با سوربیتول و زایلیتول',
        body: 'برای افرادی که نمی‌توانند طعم شیرینی را از زندگی خود حذف کنند، جایگزین‌های قند یک نجات‌بخش واقعی در حوزه دندانپزشکی هستند. این شیرین‌کننده‌ها به دو دسته تقسیم می‌شوند:\n\n۱. **قندهای الکلی طبیعی نظیر سوربیتول و زایلیتول:**\n- این ترکیبات برخلاف قندهای معمولی، توسط باکتری‌های دهان تخمیر نمی‌شوند یا با سرعتی بی‌نهایت کند تخمیر می‌شوند که پ‌هاش دهان را به حد خطرناک نمی‌رساند.\n- **زایلیتول حتی اثری معجزه‌آسا و ضدپوسیدگی دارد:** باکتری استرپتوکوک موتانس زایلیتول را مصرف می‌کند اما توانایی هضم و تغذیه از آن را ندارد؛ بنابراین انرژی باکتری هدر رفته و جمعیت میکروبی آن در دهان به شدت کاهش می‌یابد.\n- آدامس‌ها و قرص‌های نعنایی حاوی زایلیتول یا سوربیتول نه تنها دندان را خراب نمی‌کنند، بلکه جویدن آن‌ها جریان بزاق را به راه می‌اندازد و محیط اسیدی دهان را پاکسازی می‌کند.\n\n۲. **شیرین‌کننده‌های پرقدرت مصنوعی (سوکرالوز، آسپارتام، استویا):**\nاین مواد هیچ کالری کربوهیدراتی برای باکتری‌ها فراهم نمی‌کنند و کاملاً **بی‌خطر برای مینای دندان بوده و سبب پوسیدگی نمی‌شوند**. بنابراین مصرف نوشیدنی‌ها یا دسرهایی که با این مواد شیرین شده‌اند، خوراکی برای باکتری‌ها تولید نمی‌کند؛ البته به شرطی که خود نوشیدنی به دلیل وجود [اسید فسفریک و سیتریک در نوشیدنی‌های رژیمی](/articles/diet-drinks-acidity-vs-dairy-dental-protection#phosphoric-vs-citric-acid-titratable-acidity)، خاصیت اسیدی و خورندگی مستقیم روی مینای دندان نداشته باشد.',
