        body: 'بسیاری از بیماران با این تصور که نوشابه‌های بدون قند (دایت یا زیرو) و آب‌های گازدار طعم‌دار هیچ آسیبی به دندان نمی‌زنند، این محصولات را جایگزین نوشیدنی‌های معمولی می‌کنند؛ اما پس از مدتی با حساسیت شدید دندان‌ها به سرما و نازک شدن لبه دندان‌های جلو مواجه می‌شوند. برای درک این پدیده، باید تفاوت دو مکانیسم تخریب را تفکیک کرد:\n\n۱. **پوسیدگی باکتریایی دندان:** در این فرآیند، باکتری‌های پلاک میکروبی قند موجود در رژیم غذایی را تخمیر کرده و اسید تولید می‌کنند که سبب تخریب تدریجی دندان می‌شود؛ پدیده‌ای که در تحلیل [قندها، کربوهیدرات‌ها و منحنی استفان](/articles/sugars-carbohydrates-and-dental-health#how-sugars-cause-cavities-stephan-curve) تشریح شد.\n\n۲. **فرسایش اسیدی دندان:** در این حالت نیازی به فعالیت باکتری‌ها نیست. نوشیدنی‌های رژیمی حاوی مقادیر بالایی از اسیدهای صنعتی نظیر **اسید فسفریک و اسید سیتریک** هستند. تماس مستقیم این اسیدها با سطح دندان، بلورهای سخت و کلسیمی مینای دندان (هیدروکسی‌آپاتیت) را حل کرده و ضخامت لایه محافظ دندان را کاهش می‌دهد.\n\nاز نظر ساختار دندان و تعادل بزاق، حل شدن مینای دندان در محیط‌های با اسیدیته (پ‌هاش) کمتر از ۵.۵ آغاز می‌شود. در حالی که پ‌هاش (درجه اسیدی) اغلب نوشیدنی‌های رژیمی و انرژی‌زا بین **۲.۳ تا ۳.۲** متغیر است؛ یعنی محیطی شدیداً اسیدی که تعادل املاح معدنی دهان را بر هم می‌زند.',
