        body: 'میزان تخریب اسیدی صرفاً به عدد پ‌هاش (درجه اسیدی) وابسته نیست، بلکه به نوع اسید و شاخصی تحت عنوان **«ظرفیت اسیدی یا اسیدیته قابل تیتر»** بستگی دارد که نشان‌دهنده مدت‌زمانی است که بزاق برای خنثی کردن آن اسید نیاز دارد:\n\n- **اسید فسفریک:** ماده‌ای پرکاربرد در نوشابه‌های گازدار کولا که املاح کلسیم و فسفات را در ساختار مینای دندان هدف قرار داده و باعث نرم شدن و شسته شدن املاح معدنی مینا می‌شود.\n\n- **اسید سیتریک:** معمولاً در نوشیدنی‌های ورزشی و نوشابه‌های با طعم مرکبات یافت می‌شود. اسید سیتریک علاوه بر افت پ‌هاش، اثر کلاته‌کنندگی (پیوند با کلسیم و خارج کردن آن) دارد و املاح کلسیم را از بافت مینا جدا می‌کند. همچنین ظرفیت اسیدی بالای آن سبب می‌شود سیستم دفاعی بزاق دیرتر اسید را مهار کند.\n\nدر اثر حل شدن مینا، لایه زیرین آن که عاج نام دارد نمایان شده و مجاری ظریف آن تحریکات حرارتی را به عصب منتقل می‌کنند که بیمار آن را به صورت تیر کشیدن با آب سرد تجربه می‌کند.',
