        body: 'بررسی مشخصات بیوشیمیایی نوشیدنی‌ها و فرآورده‌های شیری به انتخاب رژیم غذایی مناسب کمک می‌کند:\n\n| ماده مصرفی | محدوده اسیدیته (پ‌هاش) | اثر علمی بر مینای دندان | توصیه دندانپزشکی |\n|---|---|---|---|\n| **نوشابه رژیمی (زیرو/دایت)** | ۲.۵ تا ۳.۰ (شدیداً اسیدی) | حل تدریجی مینا و افزایش حساسیت عاجی | کاهش دفعات، نوشیدن با نی و پرهیز از نگه داشتن در دهان |\n| **نوشیدنی ورزشی و انرژی‌زا** | ۲.۷ تا ۳.۲ (اسیدیته بالا) | فرسایش سریع مینا به دلیل اسید سیتریک | مصرف محدود و شستشوی بلافاصله دهان با آب ساده |\n| **شیر ساده پاستوریزه** | ۶.۵ تا ۶.۸ (خنثی) | بازسازی مواد معدنی و اشباع یونی مینا | نوشیدنی بسیار مناسب میان‌وعده برای سلامت دهان |\n| **انواع پنیر طبیعی** | ۶.۲ تا ۶.۶ (محافظتی) | تحریک قوی بزاق و خنثی‌سازی فوری اسید | مصرف به عنوان جزء پایانی وعده‌های غذایی |\n| **دوغ سنتی بدون گاز** | ۴.۵ تا ۵.۰ (اسیدی ملایم) | خنثی‌کننده مناسب پروتئینی همراه با کلسیم | جایگزین بهتر برای نوشابه‌ها با ضرورت شستشوی دهان |\n\n### چهار اصل کلینیکی برای مهار فرسایش اسیدی مینای دندان\n\n۱. **استفاده از نی در نوشیدنی‌های اسیدی:** این اقدام مسیر تماس مستقیم جریان مایع اسیدی با سطوح دندان‌های جلویی را به حداقل می‌رساند.\n\n۲. **آبکشی دهان پس از مصرف اسید:** شستشوی دهان با آب ساده غلظت اسید باقیمانده را رقیق کرده و سرعت بازگشت تعادل پ‌هاش را افزایش می‌دهد.\n\n۳. **رعایت فاصله زمانی تا مسواک زدن:** حداقل ۴۵ دقیقه زمان دهید تا ترشحات بزاقی مینای نرم‌شده را دوباره محکم و سرشار از املاح کنند، سپس از خمیردندان‌های حاوی فلوراید استفاده فرمایید.\n\n۴. **پرهیز از مصرف نوشیدنی‌های اسیدی پیش از خواب:** کاهش ترشح بزاق در طول شب، توان خنثی‌سازی اسید را به شدت افت می‌دهد؛ بنابراین دهان باید قبل از خواب کاملاً پاکسازی شود.',
