        body: 'یک ابهام متداول میان بیماران این است که آیا افزایش مصرف مکمل‌های کلسیم و ویتامین D می‌تواند پوسیدگی‌های اولیه یا سوراخ‌های ایجادشده در تاج دندان را برطرف کند؟ پاسخ دقیق علم دندانپزشکی به این پرسش **منفی** است.\n\nعلت این موضوع به ساختار طبیعی و غیرزنده مینای دندان مربوط می‌شود. مینای دندان پس از رویش، بافتی فاقد عروق خونی و فاقد سلول‌های زنده است. سلول‌های سازنده مینا (آملوبلاست‌ها) تنها در دوران رشد جوانه دندان در استخوان فک، یعنی از دوران جنینی تا حدود ۸ سالگی فعالیت دارند. با تکمیل تاج و رویش دندان در حفره دهان، این سلول‌ها از بین می‌روند و مسیر خون‌رسانی داخلی به مینا مسدود می‌شود.\n\nبنابراین، کلسیم خوراکی راهی به داخل مینای دندان رویش‌یافته در بزرگسالان ندارد. بازسازی آسیب‌های سطحی مینا صرفاً از طریق محیط موضعی دهان و به کمک کلسیم، فسفات و یون‌های فلوراید موجود در بزاق و خمیردندان‌ها صورت می‌گیرد، نه از طریق جریان خون گوارشی.',
