        body: 'سلامت بافت‌های دهان حاصل همکاری متقابل چندین ریزمغذی کلیدی است:\n\n- **منیزیم:** ماده کمکی بسیار ضروری برای فعال شدن ویتامین D در کبد و کلیه است. علاوه بر این، منیزیم استحکام ساختاری بلورهای استخوان فک را ارتقا داده و مقاومت آن را در برابر فشارهای جویدن غذا افزایش می‌دهد.\n\n- **ویتامین C:** بافت لثه و الیاف نگهدارنده دندان (که ریشه را به استخوان فک متصل نگه می‌دارند) ساختاری بر پایه پروتئین کلاژن دارند. ویتامین C عامل حیاتی در ساخت این بافت پیوندی است؛ کمبود آن موجب شکنندگی مویرگ‌های لثه و خونریزی با کمترین تحریک مسواک می‌شود.\n\n- **ویتامین K2:** فعال‌کننده پروتئین استخوان‌ساز (استئوکلسین) است که وظیفه هدایت و رسوب املاح کلسیم در بافت استخوانی فک را بر عهده دارد و مانع از رسوب کلسیم در رگ‌های خونی می‌شود.',
