        body: 'جدول زیر نقش هر یک از ریزمغذی‌ها را در ساختار بافت‌های دهان و دندان خلاصه می‌کند:\n\n| ریزمغذی | بافت هدف اصلی در دهان | نقش در سلامت دهان و دندان | منابع غذایی برتر |\n|---|---|---|---|\n| **کلسیم** | مینای دندان (در کودکی) و استخوان نگهدارنده فک (در بزرگسالی) | تامین تراکم معدنی و جلوگیری از تحلیل فک | شیر، پنیر، ماست، کنجد و بادام |\n| **ویتامین D3** | استخوان فک و سلول‌های ایمنی لثه | تنظیم جذب کلسیم و مهار بیماری‌های التهابی لثه (پریودنتال) | نور خورشید، ماهی‌های چرب، زرده تخم‌مرغ و مکمل |\n| **منیزیم** | شبکه کریستالی استخوان فک | فعال‌سازی ویتامین D و ارتقای استحکام استخوان | مغزها، حبوبات، دانه‌ها و سبزیجات برگ‌سبز |\n| **ویتامین C** | الیاف کلاژن بافت لثه | ساخت بافت کلاژن و پیشگیری از خونریزی لثه | مرکبات، کیوی، فلفل دلمه‌ای و توت‌فرنگی |\n| **ویتامین K2** | پروتئین استئوکلسین استخوان | هدایت هدفمند کلسیم به بافت استخوانی فک | لبنیات سنتی، پنیرهای تخمیرشده و زرده تخم‌مرغ |\n\n### چهار توصیه کاربردی برای سلامت طولانی‌مدت ساختار دندان‌ها\n\n۱. **پایش دوره‌ای ویتامین D خون:** میزان ویتامین D خون را سالانه بررسی کنید و در صورت وجود کمبود، زیر نظر پزشک اقدام به درمان نمایید.\n\n۲. **اولویت دریافت کلسیم از منابع طبیعی:** کلسیم دریافتی از مواد غذایی به همراه فسفر و پروتئین، میزان جذب بسیار بهتری نسبت به قرص‌های مکمل دارد.\n\n۳. **استفاده روزانه از ترکیبات موضعی فلوراید:** هیچ رژیم غذایی جایگزین محافظت موضعی فلوراید نمی‌شود؛ فلوراید خمیردندان‌ها با ایجاد لایه‌ای مقاوم و محافظ، مینای دندان را در برابر اسید باکتری‌ها نفوذناپذیر می‌سازد.\n\n۴. **اهمیت تغذیه در دوران بارداری و تکامل اولیه کودک:** تشکیل بلورهای مینای دندان‌های کودک در این دوران صورت می‌گیرد و تغذیه اصولی مادر مستقیماً کیفیت مینای دندان فرزند را پایه‌ریزی می‌کند.',
