        body: 'بسیاری از افراد با این جمله که «دندان‌های ما خانوادگی جنس خوبی ندارند و حتی با مسواک زدن هم خراب می‌شوند»، مسئولیت مراقبت از دندان‌ها را نادیده می‌گیرند. مطالعات گسترده ژنتیکی و بررسی دوقلوها نشان می‌دهد که وراثت حدود ۳۰ تا ۵۰ درصد بر ویژگی‌های ساختاری و طبیعی دهان موثر است؛ اما این تاثیرگذاری به معنای ایجاد مستقیم سوراخ یا پوسیدگی در دندان نیست.\n\nویژگی‌هایی که از والدین به ارث می‌رسند شامل موارد زیر هستند:\n- **آناتومی و عمق شیارهای دندان:** شیارهای بسیار باریک و عمیق در سطوح جونده تمیز کردن دندان را سخت‌تر می‌کنند.\n- **کیفیت و شدت جریان بزاق:** ترشح کمتر بزاق یا ظرفیت خنثی‌سازی ضعیف‌تر، محیط دهان را برای مدت طولانی‌تری اسیدی نگه می‌دارد؛ پدیده‌ای که روند اسیدی شدن آن در تحلیل [قندها، کربوهیدرات‌ها و منحنی استفان](/articles/sugars-carbohydrates-and-dental-health#how-sugars-cause-cavities-stephan-curve) به تفصیل بررسی شده است.\n- **ترتیب قرارگیری دندان‌ها در فک:** شلوغی و نامرتبی دندان‌ها دسترسی مسواک و نخ دندان را محدود می‌سازد.\n\nبا این حال، پوسیدگی یک بیماری عفونی چندعاملی است. بدون وجود **پلاک میکروبی فعال** و حضور **قندها و کربوهیدرات‌های قابل تخمیر**، ژنتیک به تنهایی هرگز قادر به حفر دندان نیست.',
