        body: 'یکی از مواردی که غالباً با پوسیدگی ارثی اشتباه گرفته می‌شود، عارضه‌ای به نام **کمبود املاح دندان‌های آسیاب و جلو (هیپومینرالیزاسیون مولر-اینسیزور یا به اختصار MIH)** یا اصطلاحاً **«دندان گچی»** است. در این حالت، دندان به محض رویش در دهان کودک، دارای لکه‌های مات به رنگ سفید گچی، زرد یا قهوه‌ای است و ظاهری شبیه به گچ دیوار دارد.\n\nتفاوت‌های بنیادین دندان گچی با پوسیدگی معمولی:\n۱. **زمان پیدایش:** دندان گچی از بدو بیرون آمدن از لثه دارای نقص است؛ در حالی که پوسیدگی باکتریایی پس از رویش و بر اثر فعالیت تدریجی اسید ایجاد می‌شود؛ تفکیک بالینی این دو حالت در راهنمای [تفاوت لکه‌های سفید اولیه با نقایص تکاملی و فلوروزیس](/articles/white-spots-enamel-caries-vs-defects#what-are-white-spot-lesions) تبیین شده است.\n۲. **علت اولیه:** دندان گچی ناشی از اختلال در مرحله رسوب املاح معدنی در دوران جنینی یا سال‌های اول زندگی (تب‌های شدید نوزادی، بیماری‌های تنفسی، عفونت‌های گوش یا کمبودهای تغذیه‌ای) است و باکتری‌ها نقشی در شروع آن ندارند.\n۳. **شکنندگی ساختاری:** مینای دندان گچی حاوی درصد بالایی پروتئین و املاح معدنی کمتر است؛ بنابراین هنگام جویدن غذاهای سفت ممکن است ناگهان خرد شود و لایه زیرین نمایان گردد.',
