        body: 'جدول زیر تفاوت ماهیت، علل و استراتژی مراقبت از دندان‌های گچی را در مقایسه با پوسیدگی میکروبی استاندارد مقایسه می‌کند:\n\n| شاخص بالینی | نقص ساختاری مینا (دندان گچی / MIH) | پوسیدگی باکتریایی ناشی از پلاک |\n|---|---|---|\n| **عامل آغازگر** | تب‌های دوره نوزادی، عوامل محیطی رشد و ژنتیک | پلاک میکروبی و تخمیر قندها در دهان |\n| **زمان مشاهده** | بلافاصله همزمان با جوانه زدن و رویش دندان | ماه‌ها پس از رویش بر اثر عدم بهداشت کافی |\n| **بافت مینا** | متخلخل، نرم و متمایل به رنگ گچی یا زرد-قهوه‌ای | سخت و سالم در ابتدا، سپس ایجاد لکه سفید و تخریب |\n| **حساسیت به لمس و آب سرد** | بسیار شدید و نیازمند خمیردندان ملایم | تنها پس از عمیق شدن پوسیدگی و درگیری عاج |\n| **درمان دندانپزشکی کلینیک** | فلوراید وارنیش دوره‌ای، روکش فلزی یا مواد ترمیمی همرنگ | برداشتن پوسیدگی، ترمیم کامپوزیت یا عصب‌کشی |\n\n### چهار اقدام کلیدی برای حفظ دندان‌های با استعداد بالای پوسیدگی\n\n۱. **فلورایدتراپی منظم کلینیکی:** همان‌گونه که در راهنمای [محافظت ضد اسید فلوراید در مینا](/articles/mouthwash-and-fluoride-therapy-guide#fluoride-remineralization-mechanism) تشریح شد، یون‌های فلوراید با نفوذ به خلل و فرج مینای متخلخل، ساختار سطحی آن را در برابر حمله اسیدی مقاوم می‌سازند.\n\n۲. **استفاده از شیارپوش دندان (فیشورسیلانت):** برای دندان‌های آسیابی که دارای شیارهای گچی یا عمیق هستند، پوشاندن شیارها با ماده محافظ شیارپوش (سیلانت) مانع از گیر غذایی و تجمع باکتری‌ها می‌شود.\n\n۳. **روکش‌های فلزی ضدزنگ دندان (SSC):** در موارد شدید تخریب دندان‌های آسیاب شیری یا دائمی اولیه، روکش‌های استاندارد مانع از خرد شدن تاج تا زمان رویش کامل می‌گردند.\n\n۴. **مراقبت بهداشتی با ابزارهای استاندارد:** استفاده از [مسواک‌های با موهای نرم](/articles/oral-hygiene-tools-brush-floss-guide#bristle-stiffness-soft-medium-hard) و تمیز کردن مداوم فواصل بین‌دندانی اجازه تشکیل لایه ضخیم پلاک باکتریایی را نخواهد داد.',
