        body: 'بزرگ‌ترین خطر اقدامات خانگی، پنهان کردن علائم هشداردهنده بدن است. دندان‌درد حاد پیام آشکاری از التهاب و درگیری عصب دندان (پالپیت) است. اگر بیمار در فاز اولیه به دندانپزشک مراجعه کند، دندان با یک درمان ریشه استاندارد یا حتی یک ترمیم ساده نجات پیدا می‌کند.\n\nعواقب تاخیر در درمان تخصصی:\n- **پیشروی باکتری‌ها به انتهای ریشه:** با مرگ عصب، باکتری‌های بی‌هوازی بدون هیچ مانعی به داخل کانال ریشه و استخوان فک نفوذ می‌کنند.\n- **ایجاد آبسه و مجرای چرکی (فیستول):** تجمع چرک در انتهای ریشه سبب تورم شدید صورت، تخریب استخوان نگهدارنده دندان و تشکیل کیست‌های چرکی می‌شود؛ وضعیتی مشابه با مراحل پیشرفته [بیماری‌های لثه و عفونت‌های پریودنتال](/articles/gum-disease-bleeding-symptoms-and-causes#gingivitis-vs-periodontitis) که استخوان فک را مستقیماً تحلیل می‌برد.\n- **کاهش شانس نگهداری دندان:** دندانی که می‌شد با درمان عصب‌کشی تا سال‌ها حفظ شود، بر اثر تخریب دیواره‌ها و استخوان اطراف، در نهایت چاره‌ای جز کشیدن و جایگزینی با ایمپلنت نخواهد داشت؛ فرایندی که شرایط آن در راهنمای [مراقبت‌های جراحی ایمپلنت دندان](/articles/dental-implant-post-op-care#bone-graft-sinus-lift-and-warning-signs) بیان شده است.',
