        body: 'راهنمای بالینی انجمن دندانپزشکی آمریکا (ADA) در سال ۲۰۲۴ برای کنترل دردهای حاد دندانی، رویکردهای دارویی ایمن را به شرح زیر توصیه می‌کند:\n\n| اقدام موقت خانگی | درجه ایمنی و علمی | نتیجه بالینی | جایگزین توصیه شده |\n|---|---|---|---|\n| **قرار دادن آسپرین روی لثه** | کاملاً مردود و خطرناک | سوختگی شیمیایی شدید و زخم لثه | بلعیدن مسکن خوراکی با یک لیوان آب |\n| **سیر خام یا پیاز روی دندان** | غیرایمن و سوزاننده | تاول و سوختگی بافت بدون درمان عفونت | شستشوی آرام دهان با سرم نمکی ولرم |\n| **شیاف یا مواد افیونی در دندان** | به شدت خطرناک | مسمومیت و تداخل دارویی با بی‌حسی | ژلوفن یا استامینوفن خوراکی استاندارد |\n| **کمپرس گرم روی صورت متورم** | خطرناک در فاز آبسه | انتشار سریع چرک و ورم به بافت نرم | کمپرس سرد از روی پوست گونه |\n\n### چهار گام اصولی برای مهار درد پیش از رسیدن به کلینیک دندانپزشکی\n\n۱. **مصرف مسکن خوراکی مناسب:** مصرف یک دوز ایبوپروفن (ژلوفن ۴۰۰ میلی‌گرم) یا استامینوفن در صورت نبود منع پزشکی و بیماری‌های گوارشی، مطمئن‌ترین راه کاهش فشار درد است.\n\n۲. **شستشوی ملایم با آب‌نمک ولرم:** غرغره آرام نصف قاشق چای‌خوری نمک در آب ولرم، با خارج کردن خرده‌های غذایی و کاهش تورم و فشار بافتی، درد موضعی را تسکین می‌دهد.\n\n۳. **استفاده از کمپرس سرد بیرونی:** قرار دادن یک کیسه یخ درون حوله روی گونه در فواصل ۱۰ دقیقه‌ای به مهار انتشار التهاب کمک شایانی می‌کند.\n\n۴. **بالا نگه داشتن سر در هنگام استراحت:** استفاده از دو بالش در هنگام خواب، فشار نبض‌دار عروق سر و دندان را کاهش داده و خوابیدن را ممکن می‌سازد.',
