        body: 'هر لکه سفیدی روی دندان ناشی از عدم رعایت بهداشت نیست. دو علت شایع دیگر وجود دارد که در دوران تشکیل دندان در کودکی ایجاد می‌شوند:\n\n۱. **فلوروزیس دندانی:** ناشی از دریافت بیش از حد مجاز فلوراید (معمولاً از طریق آب آشامیدنی با املاح بالا در سنین زیر ۶ سال) در زمان تکامل جوانه دندان است. این لکه‌ها برخلاف پوسیدگی، به صورت خطوط افقی، متقارن و در هر دو سمت فک دیده می‌شوند و جالب اینکه مینای مبتلا به فلوروزیس در برابر پوسیدگی بسیار مقاوم‌تر از دندان عادی است.\n\n۲. **کم‌رشدی و نقص تکاملی مینا (هیپوپلازی):** بر اثر تب‌های بالا، عفونت‌های ویروسی دوران نوزادی یا ضربه به دندان شیری ایجاد می‌شود و به صورت لکه‌های تک‌گیر، فرورفتگی‌ها یا شیارهای موضعی روی یک یا چند دندان خاص ظاهر می‌گردد؛ پدیده‌ای که در بررسی [ژنتیک، دندان‌های گچی و پلاک باکتریایی](/articles/genetics-chalky-teeth-vs-bacterial-plaque#what-is-chalky-teeth-mih) نیز تحلیل گردید.',
