        body: 'رویکرد درمانی بر اساس نوع و عمق لکه سفید تعیین می‌گردد:\n\n- **وارنیش فلوراید و خمیردندان‌های غنی‌شده:** همان‌گونه که در راهنمای [محافظت ضد اسید فلوراید در مینا](/articles/mouthwash-and-fluoride-therapy-guide#fluoride-remineralization-mechanism) تشریح شد، یون‌های فلوراید با نفوذ به خلل و فرج مینای متخلخل، بازسازی بلورهای هیدروکسی‌آپاتیت را تحریک می‌کنند.\n- **کلسیم فسفات فعال (CPP-ACP):** فرآورده‌های مشتق از پروتئین شیر، یون‌های کلسیم و فسفات را مستقیماً به عمق ضایعه لکه سفید تزریق می‌کنند.\n- **تکنیک نفوذ رزین همرنگ (رزین اینفیلتریشن با متد Icon):** پیشرفته‌ترین روش زیبایی بدون تراش برای محو لکه‌های سفید مقاوم پس از ارتودنسی یا فلوروزیس خفیف است. در این روش، یک ماده رزینی شفاف بسیار روان با انعکاس نور مشابه مینای سالم، به داخل منافذ لکه نفوذ کرده و سفت می‌شود؛ در نتیجه لکه سفید فوراً محو و همرنگ دندان طبیعی می‌گردد.',
