        body: 'بافت زنده داخل ریشه دندان که شامل عروق خونی، بافت همبند و رشته‌های عصبی است، در اصطلاح علمی **پالپ (مغز و بافت عصب دندان)** نامیده می‌شود. وظیفه اصلی پالپ، تغذیه و حس دندان در دوران رشد است. هنگامی که پوسیدگی سطحی مینا و عاج به موقع درمان نشود، باکتری‌های مخرب به این محفظه استریل نفوذ می‌کنند و زنجیره‌ای از التهاب‌ها را کلید می‌زنند:\n\n- **التهاب اولیه و برگشت‌پذیر عصب:** تحریک اولیه پالپ در اثر پوسیدگی یا سرمای ناگهانی، درد کوتاه چند ثانیه‌ای ایجاد می‌کند که با حذف پوسیدگی و پر کردن ساده درمان می‌شود.\n- **عفونت پیشرفته و برگشت‌ناپذیر عصب:** با نفوذ گسترده سموم باکتریایی، عروق خونی پالپ دچار پرخونی و اتساع شدید می‌شوند. از آنجا که پالپ درون دیواره‌های سخت و انعطاف‌ناپذیر عاج محصور است، فشار داخلی آن به شدت بالا رفته و دردهای شبانه ضربان‌دار، تیر کشیدن طولانی به سرما و گرما و درد خودبه‌خودی آغاز می‌گردد. در این مرحله، بافت عصب قادر به ترمیم خود نیست و **عصب‌کشی تنها راه نجات دندان** است.\n- **مرگ عصب (نکروز) و عفونت انتهای ریشه:** اگر دندان در مرحله قبل درمان نشود، بافت زنده عصب از بین می‌رود و باکتری‌ها از انتهای ریشه خارج شده و باعث تخریب استخوان فک و ایجاد کیست یا آبسه چرکی می‌شوند.',
