        body: 'برخلاف باورهای قدیمی که عصب‌کشی را درمانی دردناک و هولناک می‌دانستند، با تجهیزات مدرن امروزی این فرآیند کاملاً بدون درد و با بیشترین ظرافت انجام می‌شود:\n\n۱. **بی‌حسی عمیق و ایزولاسیون با رابردم:** با استفاده از بی‌حسی موضعی مناسب، دندان کاملاً بی‌حس می‌شود. سپس یک ورقه لاستیکی به نام رابردم روی دندان قرار می‌گیرد تا محیط کار کاملاً خشک، استریل و به دور از بزاق آلوده دهان بماند.\n۲. **دسترسی به کانال‌ها و تعیین طول دقیق ریشه:** با تراش ملایم تاج، سقف اتاقک عصب برداشته می‌شود. دندانپزشک با استفاده از دستگاه دیجیتال **اپکس‌لوکیتور** طول دقیق میلی‌متری کانال‌های ریشه را بدون نیاز به رادیوگرافی‌های مکرر اندازه می‌گیرد.\n۳. **پاکسازی مکانیکی با فایل‌های روتاری:** فایل‌های انعطاف‌پذیر نیکل-تیتانیوم که با موتورهای هوشمند می‌چرخند، دیواره‌های کانال را شکل داده و بافت عفونی و دیواره‌های آلوده را پاکسازی می‌کنند.\n۴. **شستشوی شیمیایی ضدباکتری و فعال‌سازی اولتراسونیک:** محلول‌های شستشو مانند هیپوکلریت سدیم درون کانال به جریان درمی‌آیند تا باکتری‌ها و بقایای بیوفیلم در پیچیده‌ترین ریزکانال‌ها ریشه‌کن شوند.\n۵. **پر کردن سه‌بعدی کانال‌ها با گوتاپرکا:** در نهایت، کانال تمیزشده با ماده‌ای زیست‌سازگار به نام **گوتاپرکا** (صمغ گیاهی ویژه پرکردن کانال ریشه) به همراه سیلر مخصوص به طور نفوذناپذیر مهروموم می‌شود تا راه نفوذ مجدد میکروب‌ها برای همیشه مسدود گردد.',
