        body: 'برای کنترل موثر التهاب انتهای ریشه، مصرف مسکن مناسب قبل از از بین رفتن اثر داروی بی‌حسی توصیه می‌شود:\n\n۱. **پروتکل ترکیبی طلایی:** ترکیب همزمان **ایبوپروفن ۴۰۰ میلی‌گرم + استامینوفن ۵۰۰ میلی‌گرم** هر ۶ تا ۸ ساعت (در صورت عدم منع پزشکی مانند زخم معده یا بیماری کلیوی). پژوهش‌های متعدد نشان داده این ترکیب حتی از مسکن‌های مخدردار تسکین قوی‌تری بر دردهای دندانی دارد، زیرا ایبوپروفن التهاب بافتی را از بین می‌برد و استامینوفن مسیر ادراک درد در مغز را مهار می‌کند.\n۲. **پرهیز از جویدن با دندان پانسمان‌شده:** تا زمان [ترمیم دائمی تاج و روکش نهایی برای جلوگیری از شکستن دندان](/articles/post-endodontic-restoration-crown-vs-retreatment#coronal-seal-and-timing-of-restoration)، از غذا خوردن با آن سمت فک پرهیز نمایید.\n۳. **شستشو با آب‌نمک ولرم:** غرغره ملایم آب‌نمک رقیق (نصف قاشق چای‌خوری نمک در یک لیوان آب گرم) التهاب لثه ناشی از گیره فلزی محافظ (رابردم) را به سرعت کاهش می‌دهد.',
