      'بزرگ‌ترین نگرانی بیماران پس از کشیدن دندان یا جراحی دندان عقل، **طول کشیدن خونریزی و نشت خونابه** در دهان است. در فیزیولوژی ترمیم بافت دهان، تشکیل لخته خونی درست در مرکز حفره دندان، پایه و اساس بازسازی استخوان و لثه را تشکیل می‌دهد.\n\n### دستورالعمل گام‌به‌گام کنترل خونریزی در خانه\n۱. **فشار پیوسته با گاز استریل:** گاز استریل قرار داده شده توسط جراح را با فشار یکنواخت و ملایم فک به مدت **۶۰ تا ۹۰ دقیقه** محکم نگه دارید. از باز و بسته کردن مداوم دهان یا چک کردن با زبان اکیداً خودداری کنید.\n۲. **تف نکردن آب دهان:** بزرگ‌ترین اشتباه، تف کردن پی‌درپی بزاق خونی است! تف کردن نیروی مکش منفی شدیدی در دهان ایجاد کرده و لخته نوپا را متلاشی می‌کند. بزاق دهان را به آرامی ببلعید.\n۳. **تکنیک شگفت‌انگیز چای کیسه‌ای مرطوب:** اگر پس از برداشتن گاز اول همچنان خونریزی فعال ادامه داشت، یک عدد **چای کیسه‌ای سیاه مرطوب** را با آب خنک مرطوب کرده، آب اضافه آن را بگیرید و به مدت ۳۰ تا ۴۵ دقیقه روی محل زخم فشار دهید. **اسید تانیک** موجود در چای خاصیت انقباض عروقی قوی دارد و خونریزی مویرگی را در کمترین زمان متوقف می‌سازد.\n۴. **بالا نگه داشتن سر هنگام استراحت:** در طول شب اول، از دو بالش زیر سر استفاده کنید تا با کاهش تجمع و فشار خون در ناحیه سر، خونریزی به حداقل برسد. در صورت مصرف داروهای رقیق‌کننده یا ابتلا به بیماری‌های زمینه‌ای، حتماً پیش از جراحی [راهنمای بیماری‌های سیستمیک و شرایط منع کشیدن دندان](/articles/tooth-extraction-contraindications-systemic-conditions-guidelines) را مطالعه فرمایید.',
      'یکی از دردناک‌ترین عوارض احتمالی پس از جراحی دندان‌های عقب (آسیاها) و به‌ویژه دندان عقل پایین، عارضه‌ای به نام **حفره خشک (درای ساکت یا التهاب استخوان بعد از کشیدن دندان)** است. وقتی لخته خون محافظ به هر دلیلی جدا شود، دیواره‌های استخوانی حفره دندان بدون محافظ مانده و درد شدید و ضربان‌داری ایجاد می‌شود که به سمت گوش، شقیقه و گردن تیر می‌کشد.\n\n### مهم‌ترین عوامل خطر بروز حفره خشک:\n- **استفاده از نی، سیگار و قلیان:** عمل پک زدن یا مکیدن نی در ۴۸ ساعت اول، لخته خون را مثل درپوش به بیرون می‌کشد.\n- **شستشوی شدید دهان:** غرغره کردن شدید آب‌نمک یا دهانشویه در ۲۴ ساعت اول لخته را حل می‌کند.\n- **قرص‌های ضدبارداری خوراکی:** سطح بالای هورمون استروژن تمایل بدن به حل کردن و از بین بردن لخته خون را افزایش می‌دهد.\n\n| اقدام پیشگیرانه | زمان طلایی | علت تاثیرگذاری |\n|---|---|---|\n| **پرهیز از مصرف نی و قلیان/سیگار** | تا حداقل ۷۲ ساعت | جلوگیری از مکش منفی و حفظ اکسیژن‌رسانی بافت |\n| **شستشوی ملایم با سرم فیزیولوژی** | از روز دوم به بعد | تخلیه خرده‌های غذا بدون کندن لخته نارس |\n| **استفاده از دهانشویه کلرهگزیدین ۰.۱۲٪** | قبل و بعد عمل با نظر پزشک | مهار بار میکروبی و آنزیم‌های باکتریایی حل‌کننده لخته |\n| **رژیم غذایی خنک و نرم** | روز اول و دوم | پیشگیری از آسیب مکانیکی و گشاد شدن رگ‌ها و خونریزی ناشی از گرما |',
      'تورم پس از جراحی‌های استخوانی و دندان‌های عقل نهفته، پاسخ طبیعی سیستم ایمنی به آسیب بافتی جراحی و ترشح هیستامین و واسطه‌های التهابی است. تورم معمولاً طی **۴۸ تا ۷۲ ساعت** پس از عمل به اوج خود می‌رسد و سپس سیر نزولی را آغاز می‌کند.\n\n### پروتکل زمان‌بندی سرما و گرما:\n- **۲۴ ساعت اول (فاز سرما):** کمپرس یخ (پک سرد پیچیده شده در حوله تمیز) را به صورت متناوب (**۲۰ دقیقه قرار دادن روی گونه، ۲۰ دقیقه استراحت**) استفاده کنید. سرما قطر رگ‌ها را کم کرده و از تشکیل تورم شدید بافتی جلوگیری می‌کند.\n- **از روز سوم به بعد (فاز گرما):** کمپرس ملایم و مرطوب گرم روی فک و گونه به گشاد شدن عروق و جذب سریع‌تر تورم و خون‌مردگی کمک شایانی می‌کند.\n\n### مهار درد با رویکرد دارویی هم‌افزا:\nمطالعات بالینی انجمن دندانپزشکی آمریکا (ADA) نشان می‌دهد ترکیب هم‌زمان یا چرخشی مسکن‌های غیراستروئیدی با استامینوفن، اثربخشی بالاتری نسبت به مخدرها بدون عوارض وابستگی دارد:\n- مصرف منظم **ایبوپروفن ۴۰۰ میلی‌گرم** همراه با **استامینوفن ۵۰۰ میلی‌گرم** هر ۶ تا ۸ ساعت (در صورت عدم وجود زخم معده یا بیماری کلیوی). اولین دوز مسکن را ترجیحاً پیش از برطرف شدن کامل بی‌حسی موضعی میل نمایید.',
      'دو عصب حسی مهم در مجاورت دندان‌های آسیاب پایین و عقل عبور می‌کنند:\n۱. **عصب آلوئولار تحتانی:** مسئول حس لب پایین، چانه و دندان‌های پایین همان سمت.\n۲. **عصب زبانی:** مسئول حس دوسوم جلویی زبان و طعم و مزه.\n\n### استراتژی‌های مدرن دندانپزشکی برای صفر کردن آسیب عصبی:\n- **تصویربرداری مقطعی سه‌بعدی (CBCT):** به جراح دید میلی‌متری و ۳۶۰ درجه از موقعیت کانال عصبی نسبت به انحنای ریشه‌ها می‌دهد.\n- **تکنیک جراحی تقسیم دندان:** برش ظریف تاج و ریشه‌ها با فرز جراحی، مانع از اعمال فشارهای اهرمی سنگین به کف استخوان و آسیب فشاری به کانال عصب می‌شود.\n- **کرونکتومی (برداشتن تاج دندان و حفظ ریشه):** در مواردی که نوک ریشه کاملاً دور کانال عصب حلقه زده است، جراح تنها تاج دندان را خارج کرده و ریشه‌های سالم و بدون علامت را در عمق استخوان باقی می‌گذارد تا هیچ‌گونه گزگز یا بی‌حسی در لب و چانه رخ ندهد.',
