        body: 'دندان‌های آسیاب سوم که در اصطلاح عامیانه **دندان عقل** نامیده می‌شوند، آخرین دندان‌های دائمی هستند که در قوس فکی انسان ظاهر می‌گردند. در انسان‌های اولیه به دلیل رژیم غذایی خشن، سفت و غنی از دانه‌ها و گوشت خام، فک‌ها ابعاد بسیار بزرگ‌تر و فضای کافی برای ۳۲ دندان بالغ داشتند. با گذشت هزاره‌ها و تغییر سبک تغذیه انسان به غذاهای پخته، نرم و فرآوری‌شده، نیروی جویدن کاهش یافته و طی فرآیند فرگشتی، استخوان فک انسان‌های امروزی کوچک‌تر شده است؛ این در حالی است که کد ژنتیکی تولید دندان‌های عقل همچنان در اغلب افراد فعال مانده و به همین دلیل فضای کافی در انتهای قوس فکی برای رویش مستقیم آن‌ها وجود ندارد.\n\n### تقویم زمانی رشد و تکامل دندان عقل\n- **سنین ۹ تا ۱۲ سالگی:** جوانه‌های اولیه دندان عقل در عمق استخوان فک تشکیل شده و در رادیوگرافی‌های پانورامیک به شکل لکه‌های تیره و مدور (سیاهی طبیعی جوانه دندان در رادیوگرافی) نمایان می‌شوند.\n- **سنین ۱۵ تا ۱۸ سالگی:** تاج دندان عقل به طور کامل میناسازی شده و ریشه‌زایی آغاز می‌گردد. در این بازه، دندان شروع به حرکت رو به بالا (جهت رویش در محیط دهان) می‌کند.\n- **سنین ۱۷ تا ۲۵ سالگی:** پنجره استاندارد بالینی برای رویش یا مشخص شدن وضعیت نهفتگی دندان عقل است. به همین علت که این دندان‌ها در سنین بلوغ فکری و هیجانی جوانی بیرون می‌آیند، از قدیم به آن‌ها نام دندان عقل اطلاق شده است.',
