        doctorComment:
          'بسیاری از بیماران پس از اتمام دوره ارتودنسی، با مشاهده کج شدن خفیف دندان‌های پیشین پایین، دندان عقل را متهم می‌کنند. اما مطالعات بالینی بلندمدت به وضوح نشان داده‌اند که قطع استفاده منظم از نگه‌دارنده‌ها (پلاک متحرک نگهدارنده یا سیم ثابت پشت دندانی) و رشد دیرهنگام فیزیولوژیک فک پایین عامل بازگشت نامرتبی است، نه نیروی رانش دندان عقل.',
        body: 'یکی از رایج‌ترین باورهای عمومی در جامعه این است که دندان عقل هنگام تلاش برای رویش، مانند یک بولدوزر به ردیف دندان‌های جلویی فشار آورده و باعث به‌هم‌ریختگی و کج شدن دندان‌های پیشین فک پایین می‌شود. به همین دلیل بسیاری از مراجعان اصرار بر خارج‌سازی پیشگیرانه دندان عقل صرفاً برای محافظت از ردیف دندان‌های جلو دارند.\n\n### شواهد پژوهش‌های نوین (PubMed & Cochrane)\nبررسی سیستماتیک مقالات معتبر در ژورنال انجمن دندانپزشکی آمریکا (JADA) و کتابخانه کاکرین فرضیه «فشار رو به جلو دندان عقل به عنوان عامل اصلی نامرتبی دیرهنگام» را رد کرده است:\n\n- **عدم تفاوت در افراد فاقد دندان عقل:** کارآزمایی‌های بالینی کنترل‌شده نشان می‌دهند که نامرتبی ثانویه دندان‌های پیشین پایین در افرادی که به طور مادرزادی اصلاً جوانه دندان عقل ندارند یا در نوجوانی دندان‌های عقل خود را کشیده‌اند، تقریباً با همان شیوع و شدت بروز پیدا می‌کند!\n- **رانش فیزیولوژیک به جلو:** تمام دندان‌های طبیعی در طول عمر گرایش آهسته‌ای به حرکت به سمت خط وسط دهان دارند تا سایش‌های ناشی از جویدن را جبران نمایند.\n- **رشد دیرهنگام فک پایین:** استخوان فک پایین در اواخر سنین بلوغ و تا اوایل دهه بیست زندگی، رشد خفیف استخوان فک را تجربه می‌کند که همراه با فشار طبیعی بافت نرم، تمایل دندان‌های پیشین به چرخش و بی‌نظمی را افزایش می‌دهد.\n- **توصیه علمی روز:** دندان عقل نباید صرفاً و منحصراً با هدف جلوگیری از نامرتبی دندان‌های جلویی تحت جراحی تهاجمی خارج‌سازی قرار گیرد، مگر اینکه دلایل پزشکی مشخص مانند پوسیدگی، کیست یا ضرورت درمانی ارتودنسی وجود داشته باشد.',
