        body: 'کشیدن دندان یکی از متداول‌ترین اعمال در جراحی دهان و فک است، اما هرگز نباید آن را یک مداخله ساده، موضعی و بی‌ارتباط با ارگان‌های حیاتی بدن پنداشت. حفره دهان به عنوان ورودی دستگاه گوارش و تنفس و دارای عروق و اعصاب فوق‌العاده متراکم، بازتاب‌دهنده تمام شرایط فیزیولوژیک و پاتولوژیک کل سیستم و اندام‌های بدن است. در دندانپزشکی بالینی، شرایطی که در آن‌ها خارج‌سازی دندان با ریسک شدید مرگ، خونریزی غیرقابل کنترل یا آسیب پایدار بافتی همراه است، تحت عنوان **موارد منع جراحی و کشیدن دندان** طبقه‌بندی می‌شوند.\n\n### ۱. موارد منع مطلق\nموارد منع مطلق شرایط حاد و اورژانسی پزشکی هستند که در آن‌ها هرگونه جراحی اختیاری و غیراورژانسی دندان به کلی ممنوع است تا وضعیت حیات بیمار تثبیت شود:\n- **لوسمی حاد (سرطان حاد خون):** به دلیل افت شدید پلاکت‌ها و گلبول‌های سفید موثر، کشیدن دندان می‌تواند منجر به سپسیس سیستمیک کشنده و خونریزی بندنیامدنی شود.\n- **سکته قلبی بسیار تازه (کمتر از ۱ تا ۳ ماه گذشته):** خطر آریتمی‌های کشنده و ایست قلبی ثانویه ناشی از استرس جراحی بسیار بالا است.\n- **آنژین صدری ناپایدار (درد شدید و ناپایدار قلبی):** دردی که با استراحت برطرف نمی‌شود و پیش‌درآمد سکته حاد قلبی است.\n- **فشار خون بدخیم و بحرانی (بزرگ‌تر از ۱۸۰/۱۱۰ میلی‌متر جیوه):** خطر خونریزی حاد مغزی، جداشدگی شبکیه و سکته قلبی.\n\n### ۲. موارد منع نسبی\nدر این گروه، دندان را می‌توان پس از مشاوره پزشکی با پزشک معالج، تنظیم دوز داروها، درخواست تست‌های آزمایشگاهی و فراهم ساختن تمهیدات پیشگیرانه موضعی با ایمنی کامل کشید.',
