        question: 'آیا صدای تق‌تق فک نشانه حتمی قفل شدن فک در آینده است؟',
        answer:
          'خیر. طبق مطالعات طولی، بیش از ۷۰ تا ۸۰ درصد صداهای کلیک و تق‌تق فک سال‌ها به صورت پایدار و بدون هیچ دردی باقی می‌مانند و هرگز به قفل شدن فک تبدیل نمی‌شوند. تنها در صورتی که تق‌تق با درد گزنده‌ای همراه شود یا احساس گیر کردن مقطعی داشته باشید، بررسی دندانپزشکی ضروری است.',
