        body: 'جدول زیر تفاوت نشانه‌های بالینی و اقدامات لازم در مراحل مختلف سلامت بافت اطراف ایمپلنت را خلاصه کرده است:\n\n### راهنمای بالینی تشخیص و درمان درجات مختلف سلامت و بیماری بافت اطراف ایمپلنت\n\n| وضعیت بافت دور ایمپلنت | علائم ظاهری و نشانه‌ها | وضعیت استخوان فک در رادیوگرافی | اقدام بالینی و درمانی استاندارد |\n|---|---|---|---|\n| **ایمپلنت کاملاً سالم** | لثه صورتی، محکم، بدون هیچ‌گونه خونریزی یا ترشح، ثبات استوار | تراکم استخوان در تمام جهات حفظ شده و رزوه‌ها پوشیده است | مسواک روزانه دو بار، نخ دندان سوپرفلاس و چکاپ سالانه |\n| **التهاب سطحی لثه دور ایمپلنت** | قرمزی، تورم لبه لثه، خونریزی با مسواک، بدون درد خودبه‌خودی | استخوان کاملاً سالم است و هیچ تحلیلی دیده نمی‌شود | **برگشت‌پذیر:** جرم‌گیری تخصصی لثه با قلم‌های پلاستیکی و دهان‌شویه |\n| **عفونت پیشرفته بافت اطراف پایه** | ورم شدید، ترشح چرک، بوی بد دهان، نمایان شدن رزوه‌های پیچ | تحلیل عمودی یا کاسه‌ای استخوان فک دور پایه ایمپلنت | جراحی ضدعفونی سطح فلز، پیوند استخوان و آنتی‌بیوتیک تخصصی |\n| **شکست و پس‌زدگی ایمپلنت** | لقی واضح پایه، درد شدید هنگام فشردن غذا، ترشح مداوم چرک | تخریب بیش از ۵۰ تا ۷۰ درصد استخوان نگهدارنده | خارج‌سازی پایه با جراحی ملایم، پاکسازی استخوان و ترمیم مجدد |',
